<html>
<head>
<style>
  body { margin: 0; background: #0b1020; font-family: Georgia, serif; color: #e8ecf5; overflow: hidden; }
  #stage { position: relative; width: 100vw; height: 100vh; }
  .label { position: absolute; font-size: 15px; color: #9fb0d0; letter-spacing: 0.5px; }
  .title { position: absolute; top: 18px; left: 0; width: 100%; text-align: center; font-size: 22px; color: #ffffff; }
  .sub { position: absolute; top: 52px; left: 0; width: 100%; text-align: center; font-size: 14px; color: #8fa0c0; }
  .sun { position: absolute; left: 50%; top: 50%; width: 70px; height: 70px; margin: -35px 0 0 -35px; border-radius: 50%;
         background: radial-gradient(circle at 35% 35%, #ffe9a8, #ffb347 60%, #ff8c00); box-shadow: 0 0 60px 20px rgba(255,180,80,0.5); }
  .earth { position: absolute; width: 46px; height: 46px; border-radius: 50%; }
  .axis { position: absolute; width: 3px; background: #7fd0ff; transform-origin: center; }
  .cap { position: absolute; font-size: 12px; color: #ffd27f; }
  .note { position: absolute; bottom: 30px; left: 0; width: 100%; text-align: center; font-size: 15px; color: #cfe0ff; }
</style>
</head>
<body>
<div id="stage">
  <div class="title">The tilt, not distance, makes opposite seasons</div>
  <div class="sub">Earth's axis stays pointed the same way all year</div>
  <div class="sun" id="sun"></div>
  <div class="earth" id="earth"></div>
  <div class="axis" id="axis"></div>
  <div class="cap" id="northCap">N</div>
  <div class="cap" id="southCap">S</div>
  <div class="note" id="note"></div>
</div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
<script>
  const stage = document.getElementById('stage');
  const earth = document.getElementById('earth');
  const axis = document.getElementById('axis');
  const northCap = document.getElementById('northCap');
  const southCap = document.getElementById('southCap');
  const note = document.getElementById('note');

  const cx = window.innerWidth / 2, cy = window.innerHeight / 2;
  const R = Math.min(window.innerWidth, window.innerHeight) * 0.30;
  const TILT = 23.5 * Math.PI / 180;

  // Earth orbits the sun; axis always points toward the same direction (up-right fixed)
  function place(angle) {
    const x = cx + R * Math.cos(angle);
    const y = cy + R * Math.sin(angle);
    earth.style.left = (x - 23) + 'px';
    earth.style.top = (y - 23) + 'px';
    // axis direction fixed in space: pointing up and slightly right, tilted 23.5 deg from vertical
    const ax = Math.PI / 2 - TILT; // direction of north pole in screen coords
    const len = 46;
    const x1 = x + len * Math.cos(ax);
    const y1 = y - len * Math.sin(ax);
    const x2 = x - len * Math.cos(ax);
    const y2 = y + len * Math.sin(ax);
    axis.style.left = (x1 - 1.5) + 'px';
    axis.style.top = (y1 - 1.5) + 'px';
    axis.style.width = Math.hypot(x2 - x1, y2 - y1) + 'px';
    axis.style.transform = 'rotate(' + (Math.atan2(y2 - y1, x2 - x1) * 180 / Math.PI) + 'deg)';
    axis.style.transformOrigin = '0 50%';
    northCap.style.left = (x1 - 8) + 'px';
    northCap.style.top = (y1 - 20) + 'px';
    southCap.style.left = (x2 - 8) + 'px';
    southCap.style.top = (y2 + 6) + 'px';
  }

  // Animate one full orbit, pausing at the four key positions
  const tl = gsap.timeline({ repeat: -1, repeatDelay: 1.2 });
  const keyAngles = [0, Math.PI/2, Math.PI, 3*Math.PI/2];
  const captions = [
    "June: North pole tilts toward the Sun → northern summer, southern winter",
    "September: neither pole tilts toward the Sun → autumn / spring",
    "December: South pole tilts toward the Sun → southern summer, northern winter",
    "March: neither pole tilts toward the Sun → spring / autumn"
  ];
  let t = 0;
  for (let i = 0; i < 4; i++) {
    const a0 = keyAngles[i], a1 = keyAngles[(i+1)%4];
    tl.call(() => { note.textContent = captions[i]; }, [], t);
    tl.to({}, { duration: 0.001, onUpdate: () => place(a0) }, t);
    tl.to({}, { duration: 2.4, ease: 'none', onUpdate: function(){ place(a0 + (a1-a0) * this.progress()); } }, t);
    t += 2.4;
  }
  tl.call(() => { note.textContent = captions[0]; }, [], t);
  place(0);
</script>
</body>
</html>"}

