<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', system-ui, sans-serif; background: #1a1a2e; color: #e0e0e0; display: flex; justify-content: center; align-items: center; min-height: 100vh; }
  .card-container { perspective: 1000px; width: 520px; height: 320px; cursor: pointer; }
  .card { width: 100%; height: 100%; position: relative; transform-style: preserve-3d; transition: transform 0.6s ease; }
  .card.flipped { transform: rotateY(180deg); }
  .card-face { position: absolute; width: 100%; height: 100%; backface-visibility: hidden; border-radius: 16px; display: flex; flex-direction: column; justify-content: center; align-items: center; padding: 32px; text-align: center; }
  .card-front { background: linear-gradient(135deg, #16213e, #0f3460); border: 2px solid #533483; }
  .card-back { background: linear-gradient(135deg, #533483, #e94560); transform: rotateY(180deg); }
  .card-label { font-size: 12px; text-transform: uppercase; letter-spacing: 2px; opacity: 0.6; margin-bottom: 12px; }
  .card-title { font-size: 22px; font-weight: 700; margin-bottom: 16px; }
  .card-text { font-size: 16px; line-height: 1.6; }
  .card-back .card-text { font-size: 15px; }
  .hint { font-size: 13px; opacity: 0.5; margin-top: 20px; }
  .nav { display: flex; gap: 16px; margin-top: 24px; align-items: center; }
  .nav button { background: #533483; color: white; border: none; padding: 10px 24px; border-radius: 8px; cursor: pointer; font-size: 15px; transition: background 0.2s; }
  .nav button:hover { background: #e94560; }
  .nav button:disabled { opacity: 0.3; cursor: default; }
  .counter { font-size: 14px; opacity: 0.6; min-width: 60px; text-align: center; }
  .flip-hint { font-size: 12px; opacity: 0.4; margin-top: 8px; }
</style>
</head>
<body>

<div class="card-container" id="cardContainer">
  <div class="card" id="card">
    <div class="card-face card-front">
      <div class="card-label" id="cardLabel">Card 1 of 6</div>
      <div class="card-title" id="cardTitle">Implication</div>
      <div class="card-text" id="cardFrontText">If a shape is a square, then it has four sides.</div>
      <div class="flip-hint">Click to flip</div>
    </div>
    <div class="card-face card-back">
      <div class="card-label">Answer</div>
      <div class="card-text" id="cardBackText">A square guarantees four sides. Having four sides doesn't guarantee a square — a rectangle also works. The implication only says the first guarantees the second.</div>
    </div>
  </div>
</div>

<div class="nav">
  <button id="prevBtn" onclick="prevCard()">← Prev</button>
  <span class="counter" id="counter">1 / 6</span>
  <button id="nextBtn" onclick="nextCard()">Next →</button>
</div>

<script>
const cards = [
  {
    label: "Implication",
    title: "Implication",
    front: "If a shape is a square, then it has four sides.",
    back: "A square guarantees four sides. Having four sides doesn't guarantee a square — a rectangle also works. The implication only says the first guarantees the second."
  },
  {
    label: "Converse",
    title: "Converse",
    front: "Converse of: If it rains, the ground gets wet.",
    back: "The converse flips it: If the ground is wet, then it rained. But the ground could be wet from a sprinkler — the converse isn't guaranteed by the original."
  },
  {
    label: "Contrapositive",
    title: "Contrapositive",
    front: "Contrapositive of: If it rains, the ground gets wet.",
    back: "Flip and negate: If the ground is NOT wet, then it did NOT rain. The contrapositive is always logically equivalent to the original statement."
  },
  {
    label: "Necessary Condition",
    title: "Necessary Condition",
    front: "What is a necessary condition for being a square?",
    back: "Having four sides is necessary — you can't be a square without it. But it's not enough on its own; you also need equal sides and right angles."
  },
  {
    label: "Sufficient Condition",
    title: "Sufficient Condition",
    front: "What is a sufficient condition for being a square?",
    back: "Being a rectangle with equal sides and right angles is sufficient — that guarantees it's a square. One sufficient condition is enough, even if others exist."
  },
  {
    label: "Counterexample",
    title: "Counterexample",
    front: "Counterexample to: All birds can fly.",
    back: "A penguin is a bird that cannot fly. One counterexample disproves a universal claim. The rule 'all birds fly' is false, even though many birds do fly."
  }
];

let current = 0;
const card = document.getElementById('card');
const cardContainer = document.getElementById('cardContainer');
const cardLabel = document.getElementById('cardLabel');
const cardTitle = document.getElementById('cardTitle');
const cardFrontText = document.getElementById('cardFrontText');
const cardBackText = document.getElementById('cardBackText');
const counter = document.getElementById('counter');
const prevBtn = document.getElementById('prevBtn');
const nextBtn = document.getElementById('nextBtn');

function updateCard() {
  card.classList.remove('flipped');
  setTimeout(() => {
    cardLabel.textContent = `Card ${current + 1} of ${cards.length}`;
    cardTitle.textContent = cards[current].title;
    cardFrontText.textContent = cards[current].front;
    cardBackText.textContent = cards[current].back;
    counter.textContent = `${current + 1} / ${cards.length}`;
    prevBtn.disabled = current === 0;
    nextBtn.disabled = current === cards.length - 1;
  }, 150);
}

cardContainer.addEventListener('click', () => {
  card.classList.toggle('flipped');
});

function nextCard() {
  if (current < cards.length - 1) {
    current++;
    updateCard();
  }
}

function prevCard() {
  if (current > 0) {
    current--;
    updateCard();
  }
}

updateCard();
</script>

</body>
</html>"}

